script:
$key = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings'
$backup = @{}
if (Test-Path $key) {
  $item = Get-ItemProperty -Path $key
  $backup = @{ ProxyEnable = $item.ProxyEnable; ProxyServer = $item.ProxyServer; ProxyOverride = $item.ProxyOverride; AutoConfigURL = $item.AutoConfigURL }
}
$backup | ConvertTo-Json | Set-Content -Path {{BackupFile}} -Encoding UTF8
Set-ItemProperty -Path $key -Name ProxyEnable -Value 0 -ErrorAction SilentlyContinue
Remove-ItemProperty -Path $key -Name ProxyServer -ErrorAction SilentlyContinue
Remove-ItemProperty -Path $key -Name AutoConfigURL -ErrorAction SilentlyContinue
Write-Output '已重置当前用户的代理配置（原值已备份）。'

$services = 'FDResPub','fdPHost','SSDPSRV','upnphost'
$original = @()
foreach ($name in $services) {
  $svc = Get-Service -Name $name -ErrorAction SilentlyContinue
  if ($svc) { $original += @{ Name = $name; StartType = $svc.StartType.ToString() } }
}
$original | ConvertTo-Json | Set-Content -Path {{BackupFile}} -Encoding UTF8
foreach ($name in $services) {
  Set-Service -Name $name -StartupType Manual -ErrorAction SilentlyContinue
  Start-Service -Name $name -ErrorAction SilentlyContinue
}
Write-Output ('已启用网络发现相关服务：' + ($services -join '、'))
